import 'dart:convert';
import 'package:flutter/material.dart';

class AppIcon extends StatelessWidget {
  final double? width;
  final double? height;
  final BoxFit fit;

  const AppIcon({super.key, this.width, this.height, this.fit = BoxFit.contain});

  static final _bytes = base64Decode('');

  @override
  Widget build(BuildContext context) {
    return Image.memory(
      _bytes,
      width: width,
      height: height,
      fit: fit,
      filterQuality: FilterQuality.medium,
      semanticLabel: 'אייקון הקלפי',
    );
  }
}
